import typing

class StrictTypeMeta(type):
    def __new__(mcs, name, bases, namespace):
        annotations = namespace.get('__annotations__', {})
        for key, value in namespace.items():
            if key in annotations and not key.startswith('__'):
                expected_type = annotations[key]
                if not isinstance(value, expected_type) and not isinstance(expected_type, typing._GenericAlias):
                     raise TypeError(f'Attribute {key} expected {expected_type}, got {type(value)}')
        return super().__new__(mcs, name, bases, namespace)
```
This metaclass checks the types against `__annotations__` during class creation (`__new__`). Once the class is created, there are no custom `__setattr__` or `__getattribute__` methods inserted, meaning attribute access at runtime happens at native C speed with zero overhead.

